namespace CadStudio.SolidWorks.AddinHost { public sealed class SwAddin {} }
class NativeBoreTests {
 static int passed;static string root;static JavaScriptSerializer json=CamTurnBoreBuilder.Json();
 static object Clone(object value){return json.DeserializeObject(json.Serialize(value));}
 static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);passed++;}
 static Dictionary<string,object> Row(int index,int id,int type,int feature,int count){return new Dictionary<string,object>{{"setup_index",0},{"operation_index",index},{"native_id",id},{"turn_operation_type",type},{"linked_feature_ids",new[]{feature}},{"suppressed",false},{"toolpath_generated",count>0},{"toolpath_record_counts",count>0?new[]{count}:new int[0]}};}
 static Dictionary<string,object> Tool(){return new Dictionary<string,object>{{"complete",true},{"native_id",277},{"tool_type_raw",15},{"info_raw","T02 default boring"},{"candidate",true},{"turn_tool_type_raw",1},{"insert_type_raw",1},{"holder_present",true},{"holder_type_raw",2},{"holder_id_raw",2},{"insert_dimensions_native",new Dictionary<string,object>{{"Thickness",4.7625},{"IncludedAngle",80.0},{"NoseRadius",0.4},{"InscribedCircle",12.7}}},{"holder_dimensions_native",new Dictionary<string,object>{{"BoringBarDiameter",20.0},{"ShankLength",250.0},{"LeadAngle",0.0},{"BackClearAngle",0.0},{"FrontClearAngle",0.0},{"ZInsertOffset",0.0},{"XInsertOffset",0.0},{"Protrusion",0.0},{"HolderShape",0}}},{"reason","diamond_boring_bar_requires_physical_and_geometric_qualification"}};}
 static Dictionary<string,object> Request(string name){var folder=Path.Combine(root,name);Directory.CreateDirectory(folder);var source=Path.Combine(root,"protected.SLDPRT");var archive=Path.Combine(root,"immutable.SLDPRT");var copy=Path.Combine(folder,"copy.SLDPRT");File.Copy(source,copy);var sha=CamTurnBoreBuilder.Hash(source);int[] types={7,8,1,2,14,9,3,4,13},features={74,74,75,75,76,76,77,77,78},counts={40,19,97,43,0,66,0,0,0};var rows=Enumerable.Range(0,9).Select(i=>Row(i,127+i,types[i],features[i],counts[i])).ToArray();return new Dictionary<string,object>{{"schema_version",1},{"expected_process_id",1},{"expected_process_creation_time",1234.5},{"expected_document_path",copy},{"expected_source_sha256",sha},{"protected_document_path",source},{"protected_source_sha256",sha},{"protected_part_pins",new[]{new Dictionary<string,object>{{"path",source},{"sha256",sha}},new Dictionary<string,object>{{"path",archive},{"sha256",sha}}}},{"qualification_root",folder},{"expected_sw_configuration","Default"},{"expected_cam_configuration","Mill - Metric - 0"},{"expected_inventory",new Dictionary<string,object>{{"machine_type",3},{"operation_setup_count",1},{"operation_count",9},{"operations",rows}}},{"expected_tools",new[]{Tool()}},{"selected_tool_id",277},{"feature_id",76},{"anchor_id",132},{"default_name","Default"},{"default_id",3},{"max_tools",64},{"native_receipt_path",Path.Combine(folder,"native.json")},{"expected_host_module_version_id",typeof(SwAddin).Module.ModuleVersionId.ToString()}};}
 sealed class Fake:CamTurnBoreBuilder.IBackend {
  internal readonly string Mode;internal CamTurnBoreBuilder.Request R;internal List<string> Calls=new List<string>();bool inserted,disposed;int captures;
  internal Fake(string mode){Mode=mode;}
  public void Prepare(CamTurnBoreBuilder.Request r){R=r;Calls.Add("prepare");}
  public Dictionary<string,object> Capture(){Calls.Add("capture");captures++;var inv=(Dictionary<string,object>)Clone(R.Inventory);var rows=((object[])inv["operations"]).Cast<Dictionary<string,object>>().ToList();
   if(inserted){foreach(var row in rows.Skip(6))row["operation_index"]=Convert.ToInt32(row["operation_index"])+1;rows.Insert(6,Row(6,900,5,76,0));inv["operation_count"]=10;}
   if(Mode=="route_after_insert"&&inserted)rows[0]["toolpath_record_counts"]=new[]{41};if(Mode=="route_after_read"&&captures==3)rows[5]["toolpath_record_counts"]=new[]{67};if(Mode=="before_route"&&!inserted)rows[1]["suppressed"]=true;inv["operations"]=rows;
   var tools=(object[])Clone(R.Tools);if(Mode=="tool_after_insert"&&inserted)((Dictionary<string,object>)((Dictionary<string,object>)tools[0])["insert_dimensions_native"])["NoseRadius"]=0.8;
   return new Dictionary<string,object>{{"document",new Dictionary<string,object>{{"path",R.CopyPath},{"title","copy.SLDPRT"},{"type",1},{"needs_save",Mode=="dirty"||inserted},{"configuration","Default"}}},{"configuration",new Dictionary<string,object>{{"name",R.CamConfig},{"object_name",R.CamConfig},{"associated_sw_name",R.SwConfig}}},{"inventory",inv},{"tools",tools}};
  }
  public int Insert(){Calls.Add("insert");inserted=true;if(Mode=="insert_fault")throw new COMException("partial insert",unchecked((int)0x80010105));return Mode=="old_id"?129:900;}
  public void Bind(int id){Calls.Add("bind");if(Mode=="bind_fault")throw new COMException("partial bind",unchecked((int)0x80010105));}
  public void ReadOwn(int id,Dictionary<string,object> evidence,Action persist){Calls.Add("read");evidence["tool_getter_attempted"]=true;evidence["tool_getter_returned"]=true;evidence["tool_present"]=true;evidence["tool_native_id"]=Mode=="copied_tool"?278:277;evidence["stage"]="IGetTurnNCParam";persist();if(Mode=="copied_tool")throw new InvalidOperationException("OWN_TOOL_COPY_LIFECYCLE_UNQUALIFIED");evidence["nc_getter_attempted"]=true;persist();if(Mode=="nc_fault")throw new COMException("NC failed",unchecked((int)0x80010105));evidence["nc_getter_returned"]=true;evidence["nc_present"]=true;evidence["nc_interface_verified"]=true;evidence["spindle_speed_native"]=100.0;evidence["feed_rate_ipm_native"]=1.0;evidence["units_qualified"]=false;evidence["stage"]="finished";persist();}
  public void CleanEvents(){if(Mode=="event_preflight")throw new InvalidOperationException("CAM_EVENT");}
  public object Messages {get{return new Dictionary<string,object>{{"policy","vendor_default"},{"response","default_unknown"},{"subscribed",R!=null},{"disconnected",disposed},{"active",R!=null&&!disposed},{"event_count",Mode=="late_event"&&disposed?1:0},{"events",new object[0]},{"overflow",0},{"callback_error_count",0},{"cleanup_error",Mode=="cleanup_fault"?"failure":null}};}}
  public void Dispose(){Calls.Add("dispose");disposed=true;if(Mode=="cleanup_fault")throw new Exception("cleanup failure");}
 }
 static Dictionary<string,object> Case(string name,string mode,out Fake fake,out CamTurnBoreBuilder.Request r){r=CamTurnBoreBuilder.Parse(json.Serialize(Request(name)));fake=new Fake(mode);return CamTurnBoreBuilder.Run(r,fake,CamTurnBoreBuilder.Initial());}
 static void Reject(Dictionary<string,object> r,string name){bool failed=false;try{CamTurnBoreBuilder.Parse(json.Serialize(r));}catch{failed=true;}Check(failed,name);}
 static void SharedReadTests(){
  var values=Request("shared_writer");var path=(string)values["expected_document_path"];var expected=(string)values["expected_source_sha256"];var identity=CamTurnBoreBuilder.FileIdentity(path);
  using(var writer=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.ReadWrite|FileShare.Delete)){
   Check(CamTurnBoreBuilder.Hash(path)==expected,"hash while compatible writer remains open");
   Check(CamTurnBoreBuilder.FileIdentity(path)==identity,"identity while compatible writer remains open");
   var request=CamTurnBoreBuilder.Parse(json.Serialize(values));CamTurnBoreBuilder.Files(request);
   Check(request.CopySha==expected&&request.CopyPath==Path.GetFullPath(path),"Parse and Files accept unchanged file under writer");
   writer.Position=0;writer.WriteByte(88);writer.Flush(true);
   Check(CamTurnBoreBuilder.Hash(path)!=expected,"changed content visible while writer remains open");
   bool rejected=false;try{CamTurnBoreBuilder.Files(request);}catch(InvalidOperationException e){rejected=e.Message=="SOURCE_HASH_CHANGED";}
   Check(rejected,"Files rejects changed hash under writer");
   var fake=new Fake("");var result=CamTurnBoreBuilder.Run(request,fake,CamTurnBoreBuilder.Initial());
   Check(!(bool)result["readback_verified"]&&!(bool)result["mutation_attempted"]&&!fake.Calls.Contains("insert"),"changed shared file stops before insert");
  }
 }
 static int Main(string[] args){try{root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"protected.SLDPRT"),"synthetic-part-baseline");File.WriteAllText(Path.Combine(root,"immutable.SLDPRT"),"synthetic-part-baseline");SharedReadTests();Fake f;CamTurnBoreBuilder.Request r;var x=Case("happy","",out f,out r);Check((string)x["status"]=="created_bound_nc_read_ram_only"&&(bool)x["readback_verified"],"happy accepted");Check(f.Calls.SequenceEqual(new[]{"prepare","capture","insert","capture","bind","read","capture","dispose"}),"exact ordered sequence");Check(File.Exists(r.Marker),"durable once marker");Check(!(bool)x["model_saved"]&&!(bool)x["GTP_attempted"]&&!(bool)x["production_qualified"],"RAM only");var repeat=new Fake("");var replay=CamTurnBoreBuilder.Run(r,repeat,CamTurnBoreBuilder.Initial());Check((string)replay["status"]=="error"&&!repeat.Calls.Contains("insert"),"no replay");
 foreach(var mode in new[]{"insert_fault","old_id","route_after_insert","tool_after_insert","bind_fault","nc_fault","copied_tool","route_after_read","dirty","before_route","event_preflight","late_event","cleanup_fault"}){var q=Case(mode,mode,out f,out r);Check(!(bool)q["readback_verified"]&&(string)q["status"]!="created_bound_nc_read_ram_only",mode+" rejected");Check(f.Calls.Count(z=>z=="insert")<=1&&f.Calls.Count(z=>z=="bind")<=1,mode+" no retry");if(new[]{"insert_fault","old_id","route_after_insert","tool_after_insert","dirty","before_route","event_preflight"}.Contains(mode))Check(!f.Calls.Contains("bind"),mode+" prevents bind");if(mode=="bind_fault")Check(!f.Calls.Contains("read"),"bind failure prevents NC");if(mode=="nc_fault"||mode=="copied_tool"){var own=(Dictionary<string,object>)q["own_readback"];Check(own.ContainsKey("tool_native_id")&&own["stage"].Equals("IGetTurnNCParam"),mode+" retains partial own evidence");}if((bool)q["mutation_attempted"])Check(File.Exists(r.Marker),mode+" retains marker");}
 var bad=Request("bad_source");bad["expected_source_sha256"]=new string('0',64);Reject(bad,"copy SHA mismatch");bad=Request("wrong_tool");bad["selected_tool_id"]=323;Reject(bad,"historical tool absent");bad=Request("original");bad["expected_document_path"]=bad["protected_document_path"];Reject(bad,"authoritative path excluded");bad=Request("unknown");bad["method"]="Save";Reject(bad,"unknown method rejected");bad=Request("wrong_default_type");bad["default_id"]=true;Reject(bad,"strict default type");bad=Request("archive_alias");var exclusions=(Dictionary<string,object>[])bad["protected_part_pins"];exclusions[1]["path"]=bad["expected_document_path"];Reject(bad,"immutable path excluded");bad=Request("file_changed");r=CamTurnBoreBuilder.Parse(json.Serialize(bad));File.AppendAllText(r.CopyPath,"changed");f=new Fake("");x=CamTurnBoreBuilder.Run(r,f,CamTurnBoreBuilder.Initial());Check(!(bool)x["readback_verified"]&&!f.Calls.Contains("insert"),"source changed before native rejected");
 Console.WriteLine(json.Serialize(new{status="passed",passed=passed,failed=0,native_called=false,COM_activated=false,test_root=root}));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
